const i=[{id:"antibiotics-001",topicId:"antibiotics",question:"Для борьбы с какими заболеваниями предназначены антибиотики?",options:["Вызванными бактериальной микрофлорой","Вызванными вирусами","Вызванными паразитами","Вызванными грибковой микрофлорой"],correctIndex:0,explanation:"Антибиотики — это лекарственные препараты, предназначенные для борьбы с заболеваниями, вызванными бактериальной микрофлорой.",difficulty:"easy",tags:["определение"]},{id:"antibiotics-002",topicId:"antibiotics",question:"Эффективны ли антибиотики при гриппе и ОРВИ?",options:["Да, они одинаково действуют на бактерии и вирусы","Да, но только в высоких дозах","Нет, антибиотики не действуют на вирусы","Да, если применять их с первого дня болезни"],correctIndex:2,explanation:"Антибиотики эффективны только против бактерий и не действуют на вирусы, например при гриппе или ОРВИ.",difficulty:"easy",tags:["фармакология","показания"]},{id:"antibiotics-003",topicId:"antibiotics",question:"Какие инфекции называются антропонозами?",options:["Инфекции, передающиеся человеку от животных","Инфекции, источником которых является только человек","Инфекции, передающиеся через укусы насекомых","Инфекции, возникающие только в лечебных учреждениях"],correctIndex:1,explanation:"Антропонозы — инфекции, источником которых является только человек.",difficulty:"medium",tags:["инфекции","классификация"]},{id:"antibiotics-004",topicId:"antibiotics",question:"Что такое зоонозы?",options:["Инфекции, источником которых является только человек","Инфекции, передающиеся исключительно половым путём","Инфекции, возникающие при контакте с почвой","Инфекции, передающиеся человеку от животных"],correctIndex:3,explanation:"Зоонозы — инфекции, передающиеся человеку от животных.",difficulty:"medium",tags:["инфекции","классификация"]},{id:"antibiotics-005",topicId:"antibiotics",question:"По какому признаку инфекционные заболевания делят на антропонозы и зоонозы?",options:["По источнику заражения","По тяжести течения","По чувствительности к антибиотикам","По длительности инкубационного периода"],correctIndex:0,explanation:"Инфекционные заболевания классифицируются по источнику заражения на антропонозы и зоонозы.",difficulty:"medium",tags:["инфекции","классификация"]},{id:"antibiotics-006",topicId:"antibiotics",question:"Как происходит заражение при аэрогенном пути передачи инфекции?",options:["Через употребление заражённой пищи или воды","При вдыхании частиц слюны или пыли","Через укусы кровососущих насекомых","При соприкосновении с предметами обихода"],correctIndex:1,explanation:"Аэрогенный (воздушно-капельный) путь передачи реализуется при вдыхании частиц слюны или пыли.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-007",topicId:"antibiotics",question:"Какие заболевания приведены как примеры аэрогенного пути передачи?",options:["Холера и сальмонеллёз","Чума и малярия","Туберкулёз и дифтерия","Клещевой боррелиоз и гепатит"],correctIndex:2,explanation:"Примерами инфекций с аэрогенным путём передачи являются туберкулёз и дифтерия.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-008",topicId:"antibiotics",question:"Какое второе название имеет фекально-оральный путь передачи инфекции?",options:["Трансмиссивный","Контактный","Воздушно-капельный","Алиментарный"],correctIndex:3,explanation:"Фекально-оральный путь передачи также называется алиментарным — заражение происходит через употребление заражённой пищи или воды.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-009",topicId:"antibiotics",question:"Какие инфекции передаются фекально-оральным путём?",options:["Холера и сальмонеллёз","Туберкулёз и дифтерия","Чума и малярия","Клещевой боррелиоз"],correctIndex:0,explanation:"Примерами инфекций с фекально-оральным (алиментарным) путём передачи являются холера и сальмонеллёз.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-010",topicId:"antibiotics",question:"Каким образом реализуется контактный путь передачи инфекции?",options:["Только при вдыхании заражённой пыли","При соприкосновении с кожей или слизистыми больного, через предметы обихода, кровь и при половых контактах","Исключительно через укусы кровососущих насекомых","Только через воду из открытых водоёмов"],correctIndex:1,explanation:"Контактный путь передачи реализуется при соприкосновении с кожей или слизистыми больного, через предметы обихода, а также через кровь и при половых контактах.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-011",topicId:"antibiotics",question:"Через что передаётся инфекция при трансмиссивном пути заражения?",options:["Через предметы обихода","Через заражённую воду","Через укусы кровососущих насекомых","Через вдыхание частиц слюны"],correctIndex:2,explanation:"Трансмиссивный путь передачи реализуется через укусы кровососущих насекомых.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-012",topicId:"antibiotics",question:"Какие заболевания названы примерами трансмиссивного пути передачи?",options:["Туберкулёз, дифтерия, грипп","Холера, сальмонеллёз, дизентерия","Гепатит, ВИЧ, сифилис","Клещевой боррелиоз, чума, малярия"],correctIndex:3,explanation:"Примерами инфекций с трансмиссивным путём передачи являются клещевой боррелиоз, чума и малярия.",difficulty:"medium",tags:["инфекции","пути передачи"]},{id:"antibiotics-013",topicId:"antibiotics",question:"Какое исследование необходимо для подбора эффективной антибиотикотерапии?",options:["Бактериологическое исследование (посев биоматериала)","Общий анализ мочи","Ультразвуковое исследование органов брюшной полости","Электрокардиография"],correctIndex:0,explanation:"Для подбора эффективной терапии необходимо проведение бактериологического исследования — посева биоматериала, что позволяет точно идентифицировать возбудителя.",difficulty:"medium",tags:["диагностика","принципы назначения"]},{id:"antibiotics-014",topicId:"antibiotics",question:"Что представляет собой антибиотикограмма?",options:["График изменения температуры на фоне лечения","Тест на чувствительность микроорганизма к различным группам препаратов","Схему приёма препарата по часам","Перечень побочных эффектов антибиотика"],correctIndex:1,explanation:"Антибиотикограмма — тест на чувствительность микроорганизма к различным группам препаратов, ключевой этап диагностики.",difficulty:"medium",tags:["диагностика","принципы назначения"]},{id:"antibiotics-015",topicId:"antibiotics",question:"Как ведут себя чувствительные штаммы бактерий при воздействии антибиотика?",options:["Сохраняют жизнеспособность и продолжают размножаться","Приобретают устойчивость в течение нескольких часов","Их рост эффективно подавляется или они уничтожаются","Переходят в спорообразующую форму"],correctIndex:2,explanation:"У чувствительных штаммов антибиотик эффективно подавляет рост или уничтожает бактерии.",difficulty:"medium",tags:["резистентность"]},{id:"antibiotics-016",topicId:"antibiotics",question:"Чем характеризуются устойчивые (резистентные) штаммы бактерий?",options:["Их рост полностью подавляется препаратом","Они погибают только при повышении дозы вдвое","Они чувствительны ко всем группам антибиотиков","Они сохраняют жизнеспособность даже при воздействии препарата"],correctIndex:3,explanation:"Устойчивые (резистентные) штаммы сохраняют жизнеспособность даже при воздействии препарата.",difficulty:"medium",tags:["резистентность"]},{id:"antibiotics-017",topicId:"antibiotics",question:"К развитию какой глобальной проблемы ведёт бесконтрольный приём антибиотиков?",options:["Антибиотикорезистентности","Гиповитаминоза","Аутоиммунных заболеваний","Хронической почечной недостаточности"],correctIndex:0,explanation:"Бесконтрольный приём антибиотиков ведёт к развитию антибиотикорезистентности, когда привычные лекарства перестают действовать на мутировавшие бактерии.",difficulty:"easy",tags:["резистентность"]},{id:"antibiotics-018",topicId:"antibiotics",question:"Как следует принимать антибиотики согласно правилам?",options:["До исчезновения симптомов, затем прекратить","Строго по назначению врача и полным курсом","По собственному усмотрению при первых признаках болезни","Через день для снижения нагрузки на печень"],correctIndex:1,explanation:"Принимать антибиотики следует строго по назначению врача и полным курсом — это предотвращает развитие антибиотикорезистентности.",difficulty:"easy",tags:["принципы назначения"]},{id:"antibiotics-019",topicId:"antibiotics",question:"Какое жизнеугрожающее состояние может развиться при реакции гиперчувствительности на антибиотик?",options:["Гипертонический криз","Кардиогенный шок","Анафилактический шок","Тромбоэмболия лёгочной артерии"],correctIndex:2,explanation:"Применение антибиотиков сопряжено с риском развития реакций гиперчувствительности вплоть до анафилактического шока — жизнеугрожающего состояния.",difficulty:"medium",tags:["осложнения","аллергия"]},{id:"antibiotics-020",topicId:"antibiotics",question:"На какой области тела обычно проводились кожные пробы на антибиотики?",options:["На передней поверхности бедра","На спине между лопатками","На тыльной стороне кисти","На внутренней поверхности предплечья"],correctIndex:3,explanation:"Кожные пробы обычно выполнялись на внутренней поверхности предплечья.",difficulty:"medium",tags:["кожные пробы","аллергия"]},{id:"antibiotics-021",topicId:"antibiotics",question:"Какие изменения в месте введения считаются положительным результатом кожной пробы?",options:["Отёк, гиперемия или зуд","Побледнение и похолодание кожи","Уплотнение без покраснения","Локальное снижение чувствительности"],correctIndex:0,explanation:"Отёк, гиперемия (покраснение) или зуд в месте введения считаются положительным результатом кожной пробы.",difficulty:"medium",tags:["кожные пробы","аллергия"]},{id:"antibiotics-022",topicId:"antibiotics",question:"Что означает положительный результат кожной пробы на антибиотик?",options:["Необходимость снизить дозу препарата вдвое","Абсолютное противопоказание к применению данного препарата","Возможность применения препарата под наблюдением врача","Необходимость повторить пробу через сутки"],correctIndex:1,explanation:"Положительный результат кожной пробы является абсолютным противопоказанием к применению данного препарата.",difficulty:"medium",tags:["кожные пробы","противопоказания"]},{id:"antibiotics-023",topicId:"antibiotics",question:"По какой причине в современной международной практике изменилось отношение к кожным пробам?",options:["Из-за высокой стоимости проведения пробы","Из-за длительности ожидания результата","Из-за низкой прогностической ценности — анафилаксия фиксировалась и при отрицательных результатах","Из-за того, что проба сама по себе вызывает резистентность"],correctIndex:2,explanation:"Отношение к кожным пробам изменилось из-за их низкой прогностической ценности: зафиксированы случаи анафилаксии при отрицательных результатах пробы.",difficulty:"hard",tags:["кожные пробы","аллергия"]},{id:"antibiotics-024",topicId:"antibiotics",question:"Где предпочтительно проводить введение антибиотика, особенно первое?",options:["В домашних условиях под наблюдением родственников","В любом месте при наличии шприца и препарата","На рабочем месте пациента","В медицинском учреждении, оснащённом укладкой для помощи при анафилактическом шоке"],correctIndex:3,explanation:"Введение антибиотиков, особенно первое, предпочтительно проводить в условиях медицинского учреждения, оснащённого укладкой для оказания экстренной помощи при анафилактическом шоке.",difficulty:"medium",tags:["безопасность","принципы назначения"]},{id:"antibiotics-025",topicId:"antibiotics",question:"Какие требования предъявляются к работе с антибиотиками во флаконах (порошок)?",options:["Строгое соблюдение правил асептики и выбор соответствующего растворителя","Обязательное подогревание флакона перед разведением","Использование только стеклянных шприцев","Разведение непосредственно перед сном пациента"],correctIndex:0,explanation:"Антибиотики во флаконах (порошок) требуют строгого соблюдения правил асептики и выбора соответствующего растворителя.",difficulty:"medium",tags:["разведение","техника"]},{id:"antibiotics-026",topicId:"antibiotics",question:"Какие растворители используются для разведения антибиотика при внутривенном введении?",options:["Раствор прокаина или лидокаина","Дистиллированная вода для инъекций или 0,9% раствор натрия хлорида","Охлаждённая кипячёная вода","Раствор глюкозы с добавлением анестетика"],correctIndex:1,explanation:"Для внутривенного введения используется дистиллированная вода для инъекций или 0,9% раствор натрия хлорида (физиологический раствор).",difficulty:"medium",tags:["разведение","техника"]},{id:"antibiotics-027",topicId:"antibiotics",question:"Что категорически запрещено использовать для разведения антибиотика при внутривенном введении?",options:["Физиологический раствор натрия хлорида","Дистиллированную воду для инъекций","Местные анестетики (лидокаин, новокаин)","Стерильные одноразовые шприцы"],correctIndex:2,explanation:"Использование местных анестетиков (лидокаина, новокаина) для внутривенного введения категорически запрещено.",difficulty:"hard",tags:["разведение","безопасность"]},{id:"antibiotics-028",topicId:"antibiotics",question:"С какой целью при внутримышечном введении антибиотика применяют местные анестетики?",options:["Для ускорения всасывания препарата","Для продления действия антибиотика","Для предупреждения аллергической реакции","Для уменьшения болезненности инъекции"],correctIndex:3,explanation:"При внутримышечном введении местные анестетики применяются с целью уменьшения болезненности инъекции.",difficulty:"medium",tags:["разведение","техника"]},{id:"antibiotics-029",topicId:"antibiotics",question:"Какой концентрации раствор прокаина (новокаина) используется для разведения антибиотика при внутримышечном введении?",options:["0,5%","0,9%","1%","2%"],correctIndex:0,explanation:"Для внутримышечного введения применяется 0,5% раствор прокаина (новокаина).",difficulty:"hard",tags:["разведение","техника"]},{id:"antibiotics-030",topicId:"antibiotics",question:"Какой растворитель используется при внутримышечном введении, если местные анестетики противопоказаны?",options:["Раствор глюкозы 5%","Вода для инъекций или 0,9% раствор натрия хлорида","Охлаждённая кипячёная вода","Раствор Рингера"],correctIndex:1,explanation:"Если анестетики противопоказаны, для внутримышечного введения используют воду для инъекций или 0,9% раствор натрия хлорида.",difficulty:"medium",tags:["разведение","техника"]},{id:"antibiotics-031",topicId:"antibiotics",question:"Чем и до какого уровня разводятся порошки для приготовления суспензий при пероральном приёме?",options:["Дистиллированной водой до половины флакона","Физиологическим раствором на глаз","Охлаждённой кипячёной водой строго до метки на флаконе","Горячей водой до полного растворения порошка"],correctIndex:2,explanation:"Для перорального приёма порошки для приготовления суспензий разводятся охлаждённой кипячёной водой строго до метки на флаконе.",difficulty:"medium",tags:["разведение","техника"]},{id:"antibiotics-032",topicId:"antibiotics",question:"Сколько миллилитров дистиллированной воды нужно добавить к 2 мл 2% лидокаина, чтобы получить 1% раствор?",options:["0,5 мл","1 мл","4 мл","2 мл"],correctIndex:3,explanation:"К 2 мл 2% лидокаина добавляют 2 мл дистиллированной воды, в результате получают 4 мл 1% раствора лидокаина.",difficulty:"hard",tags:["разведение","расчёты"]},{id:"antibiotics-033",topicId:"antibiotics",question:"Какой объём 1% раствора лидокаина получится при смешивании 2 мл 2% лидокаина и 2 мл дистиллированной воды?",options:["4 мл","2 мл","3 мл","6 мл"],correctIndex:0,explanation:"При смешивании 2 мл 2% лидокаина и 2 мл дистиллированной воды получают 4 мл 1% раствора лидокаина.",difficulty:"hard",tags:["разведение","расчёты"]},{id:"antibiotics-034",topicId:"antibiotics",question:"На какие четыре группы делятся бета-лактамные антибиотики?",options:["Макролиды, тетрациклины, аминогликозиды, фторхинолоны","Пенициллины, цефалоспорины, карбапенемы, монобактамы","Сульфаниламиды, нитрофураны, линкозамиды, гликопептиды","Пенициллины, макролиды, карбапенемы, тетрациклины"],correctIndex:1,explanation:"Бета-лактамные антибиотики делятся на пенициллины, цефалоспорины, карбапенемы и монобактамы.",difficulty:"medium",tags:["классификация","бета-лактамы"]},{id:"antibiotics-035",topicId:"antibiotics",question:"Какая из перечисленных групп НЕ относится к бета-лактамным антибиотикам?",options:["Пенициллины","Цефалоспорины","Макролиды","Карбапенемы"],correctIndex:2,explanation:"К бета-лактамным антибиотикам относятся пенициллины, цефалоспорины, карбапенемы и монобактамы. Макролиды в эту группу не входят.",difficulty:"medium",tags:["классификация","бета-лактамы"]},{id:"antibiotics-036",topicId:"antibiotics",question:"Какое действующее вещество относится к группе пенициллинов?",options:["Цефтриаксон","Цефуроксим","Цефепим","Амоксициллин"],correctIndex:3,explanation:"Амоксициллин относится к группе пенициллинов, тогда как цефтриаксон, цефуроксим и цефепим — цефалоспорины.",difficulty:"medium",tags:["пенициллины","препараты"]},{id:"antibiotics-037",topicId:"antibiotics",question:"Какое из перечисленных действующих веществ входит в группу пенициллинов?",options:["Ампициллин","Цефазолин","Цефотаксим","Цефтазидим"],correctIndex:0,explanation:"Ампициллин относится к пенициллинам; цефазолин, цефотаксим и цефтазидим — представители цефалоспоринов.",difficulty:"medium",tags:["пенициллины","препараты"]},{id:"antibiotics-038",topicId:"antibiotics",question:"С каким веществом комбинируется амоксициллин в защищённых пенициллинах?",options:["С сульбактамом","С клавулановой кислотой","С метронидазолом","С тазобактамом"],correctIndex:1,explanation:"Амоксициллин комбинируется с клавулановой кислотой; ампициллин — с сульбактамом.",difficulty:"hard",tags:["пенициллины","препараты"]},{id:"antibiotics-039",topicId:"antibiotics",question:"С каким веществом комбинируется ампициллин согласно таблице пенициллинов?",options:["С клавулановой кислотой","С лидокаином","С сульбактамом","С прокаином"],correctIndex:2,explanation:"В таблице пенициллинов приведена комбинация ампициллина с сульбактамом.",difficulty:"hard",tags:["пенициллины","препараты"]},{id:"antibiotics-040",topicId:"antibiotics",question:"Какое действующее вещество относится к цефалоспоринам?",options:["Амоксициллин","Ампициллин","Бензилпенициллин","Цефтриаксон"],correctIndex:3,explanation:"Цефтриаксон относится к цефалоспоринам; амоксициллин, ампициллин и бензилпенициллин — пенициллины.",difficulty:"medium",tags:["цефалоспорины","препараты"]},{id:"antibiotics-041",topicId:"antibiotics",question:"Какое из перечисленных веществ входит в группу цефалоспоринов?",options:["Цефиксим","Амоксициллин","Клавулановая кислота","Сульбактам"],correctIndex:0,explanation:"Цефиксим относится к цефалоспоринам. Амоксициллин — пенициллин, а клавулановая кислота и сульбактам — вещества, комбинируемые с пенициллинами.",difficulty:"medium",tags:["цефалоспорины","препараты"]},{id:"antibiotics-042",topicId:"antibiotics",question:"В перечне ниже одно вещество является пенициллином, а остальные — цефалоспоринами. Укажите его.",options:["Цефалексин","Бензилпенициллин","Цефпрозил","Цефаклор"],correctIndex:1,explanation:"Бензилпенициллин относится к пенициллинам. Цефалексин, цефпрозил и цефаклор — цефалоспорины.",difficulty:"medium",tags:["цефалоспорины","препараты"]}];export{i as default};
